import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_createContextual_TriageGen0Test {

    private StringArrayDeserializer deserializer;
    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType stringType;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        stringType = mock(JavaType.class);

        when(ctxt.constructType(String.class)).thenReturn(stringType);
    }









    /**
     * Test Case 5:
     * Scenario: findConvertingContentDeserializer returns a deserializer that is the same as _elementDeserializer.
     * Result: returns 'this'.
     */
    @Test
    public void testCreateContextual_ReturnsThisWhenNoChange() throws JsonMappingException {
        // To test this, we need to set _elementDeserializer. 
        // Since it's private, we use a trick or rely on the default which is null.
        // If _elementDeserializer is null, and findConvertingContentDeserializer returns null, 
        // it enters the first branch.

        // Let's try the branch where deser != null but deser == _elementDeserializer.
        // This happens if findConvertingContentDeserializer returns the existing _elementDeserializer.

        // We'll use a subclass to expose the field for testing or use reflection if needed, 
        // but here we can just mock the logic.

        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());
        // In default state, _elementDeserializer is null.
        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(null);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);
        assertSame(spyDeserializer, result);
    }
}
